from scipy.optimize import least_squares
q0=np.array([-.00278,.88372,3.14048,-2.36176,.01304,.39766,1.58454]);A=np.array([[0,0,-1],[0,1,0],[0,0,-1],[0,1,0],[0,0,-1],[0,1,0],[0,0,-1]],float);L=[.1284,.2104,.2104,.2084,.1059,.106,.2054];p0=np.array([.1199,0,.5512])
def R(a,t):
 a=a/np.linalg.norm(a);K=np.array([[0,-a[2],a[1]],[a[2],0,-a[0]],[-a[1],a[0],0]]);return np.eye(3)*np.cos(t)+(1-np.cos(t))*np.outer(a,a)+np.sin(t)*K
def fk(q):
 T=np.eye(3);p=p0.copy()
 for i in range(7):T=T@R(A[i],q[i]);p+=T@np.array([0,0,L[i]])
 return p,T
